@Override
    public List<ReconExecPlanDo> queryExecPlansByDate(String reconStartDt, String reconEndDt) {
        return reconExecPlanDoMapper.queryExecPlansByDate(reconStartDt, reconEndDt);
    }

public void runReconExecPlanByDate(String reconStartDt, String reconEndDt, Boolean isExecNextPlan) {
        List<ReconExecPlanDo> availableReconExecPlans = reconExecPlanDoTunnel.queryExecPlansByDate(reconStartDt, reconEndDt);
        if (CollectionUtils.isEmpty(availableReconExecPlans)) {
            return;
        }
        runReconExecPlan(availableReconExecPlans, isExecNextPlan);
    }

private void runReconExecPlan(List<ReconExecPlanDo> availableReconExecPlans, Boolean isExecNextPlan) {
        List<String> reconRuleIdList = availableReconExecPlans.stream().map(ReconExecPlanDo::getReconRuleId).collect(Collectors.toList());

        //取已激活的对账规则
        List<ReconRuleConfigDo> reconRuleConfigDoList = reconRuleConfigDoTunnel.queryRuleConfigByRuleIdList(reconRuleIdList, ActivedEnum.READY_ACTIVED.getCode());
        if (CollectionUtils.isEmpty(reconRuleConfigDoList)) {
            return;
        }
        Map<String, ReconRuleConfigDo> reconRuleConfigDoMap = reconRuleConfigDoList.stream().collect(Collectors.toMap(ReconRuleConfigDo::getReconRuleId, a -> a, (v1, v2) -> v2));

        //执行任务
        for (ReconExecPlanDo reconExecPlanDo : availableReconExecPlans) {
            ReconRuleConfigDo reconRuleConfigDo = reconRuleConfigDoMap.get(reconExecPlanDo.getReconRuleId());
            //配置未启用，直接返回
            if (reconRuleConfigDo == null) {
                continue;
            }
            //获取动态配置
            RunManualDagNodesRequest runManualDagNodesRequest = this.getRunManualDagNodesRequest(reconExecPlanDo, reconRuleConfigDo, isExecNextPlan);
            if (runManualDagNodesRequest == null) {
                continue;
            }
            try {
                if (StringUtils.isNotEmpty(reconExecPlanDo.getObjectNo())) {
                    //请求结算上传汇总数据
                    SummarySettleCreateDto createDto = new SummarySettleCreateDto();
                    createDto.setSettleOrderNo(reconExecPlanDo.getObjectNo());
                    if (reconExecPlanDo.getIsObjectNew() == 0) {
                        createDto.setIsNew(false);
                    } else {
                        createDto.setIsNew(true);
                    }
                    log.info("createSummarySettleOrder request: " + JSON.toJSONString(createDto));
                    Response<String> settleOrderResponse = settleOrderNewService.createSummarySettleOrder(createDto);
                    log.info("createSummarySettleOrder response: " + JSON.toJSONString(settleOrderResponse));
                }
            } catch (Exception e) {
                log.warn("createSummarySettleOrder param{}", reconExecPlanDo.getObjectNo());
                log.warn("createSummarySettleOrder error", e);
            }
            RunManualDagNodesResponse runManualDagNodesResponse = ReconOdpsUtil.runManualDagNodes(runManualDagNodesRequest, reconOdpsConfig);
            if (runManualDagNodesResponse == null) {
                log.warn("runManualDagNodes error, param:{}", JSON.toJSONString(runManualDagNodesRequest));
                dingErrorMsgComponent.sendAlarm("对账任务调度失败!, execPlanId:{}", reconExecPlanDo.getExecPlanId());
                continue;
            }
            Long dagId = runManualDagNodesResponse.getDagId();
            if (isExecNextPlan) {
                reconExecPlanDoTunnel.updateFileMakeStatusByPlanId(reconExecPlanDo.getExecPlanId(), ExecPlanStatusEnum.READY_CALL.getCode(), dagId);
            } else {
                reconExecPlanDoTunnel.updateReconExecPlanByPlanId(reconExecPlanDo.getExecPlanId(), ExecPlanStatusEnum.READY_CALL.getCode(), dagId, runManualDagNodesRequest.getProjectEnv());

            }
        }
    }

