public void runReconExecPlan(String date, String billPeriod, Boolean isExecNextPlan) {
        Response<List<SettleBillNewDto>> response = reinsSettleOrderService.queryReinsBillByPeriod(billPeriod);
        if(!response.isSuccess() || null == response.getContent()) {
            return;
        }
        //执行任务
        String currentDate = Strings.isNullOrEmpty(date) ? DateUtil.dateToString(new Date()) : date;
        Map<String, List<SettleBillNewDto>> settleBillMap = response.getContent().stream().collect(Collectors.groupingBy(bill -> String.format(Constant.REINS_GROUP, bill.getContractNo(), bill.getCounterpartCode(), bill.getSubCounterpartCode())));
        for (Map.Entry<String, List<SettleBillNewDto>> billMap : settleBillMap.entrySet()) {
            Map<String, List<SettleBillNewDto>> feeTypeMap = billMap.getValue().stream().collect(Collectors.groupingBy(SettleBillNewDto::getSettleFeeTypeCd));
            boolean flag = false;
            for(Map.Entry<String, List<SettleBillNewDto>> feeTypeMapF : feeTypeMap.entrySet()) {
                ReconRuleConfigDo reconRuleConfigDo = new ReconRuleConfigDo();
                ReinsDagParametersVO parametersVO = new ReinsDagParametersVO();
                if(SettleFeeType.AMORTIZED_COMPENSATION_EXPENSES.getCode().equals(feeTypeMapF.getKey())) {
                    List<SettleBillNewDto> billList0502 = feeTypeMapF.getValue();
                    SettleBillNewDto billNewDto = billList0502.get(0);
                    reconRuleConfigDo.setReconBillType(Constant.REINS_CLAIM);
                    parametersVO.setPt(String.format(Constant.REINS_PT, currentDate, billMap.getKey()));
                    parametersVO.setBillNo0502(billList0502.stream().map(SettleBillNewDto::getSettleBillNo).collect(Collectors.joining(",")));
                    parametersVO.setBillPeriod(billPeriod);
                    parametersVO.setContractNo(billNewDto.getContractNo());
                    parametersVO.setDate(currentDate);
                    parametersVO.setSo1(billNewDto.getCounterpartCode());
                    parametersVO.setSo2(billNewDto.getSubCounterpartCode());
                } else if(!flag){
                    flag = true;
                    reconRuleConfigDo.setReconBillType(Constant.REINS_SETTLE);
                    List<SettleBillNewDto> billList0501 = feeTypeMap.get(SettleFeeType.CEDED_PREMIUM.getCode());
                    List<SettleBillNewDto> billList0503 = feeTypeMap.get(SettleFeeType.REINSURANCE_EXPENSES.getCode());
                    SettleBillNewDto billNewDto = null == billList0501 ? billList0503.get(0) : billList0501.get(0);
                    parametersVO.setPt(String.format(Constant.REINS_PT, currentDate, billMap.getKey()));
                    if(null != billList0501) {
                        parametersVO.setBillNo0501(billList0501.stream().map(SettleBillNewDto::getSettleBillNo).collect(Collectors.joining(",")));
                    }
                    if(null != billList0503) {
                        parametersVO.setBillNo0503(billList0503.stream().map(SettleBillNewDto::getSettleBillNo).collect(Collectors.joining(",")));
                    }
                    parametersVO.setBillPeriod(billPeriod);
                    parametersVO.setContractNo(billNewDto.getContractNo());
                    parametersVO.setDate(currentDate);
                    parametersVO.setSo1(billNewDto.getCounterpartCode());
                    parametersVO.setSo2(billNewDto.getSubCounterpartCode());
                }

                //获取动态配置
                RunManualDagNodesRequest runManualDagNodesRequest = this.getRunManualDagNodesRequest(parametersVO, reconRuleConfigDo, isExecNextPlan);
                if (runManualDagNodesRequest == null) {
                    continue;
                }
                RunManualDagNodesResponse runManualDagNodesResponse = ReconOdpsUtil.runManualDagNodes(runManualDagNodesRequest, reconOdpsConfig);
                if (runManualDagNodesResponse == null) {
                    log.warn("runManualDagNodes error, param:{}", JSON.toJSONString(runManualDagNodesRequest));
                    dingErrorMsgComponent.sendAlarm("对账任务调度失败!, pt:{}", parametersVO.getPt());
                    continue;
                }
            }
        }
    }

